bad = []
for c in C:
    ids = [s['id'] for s in c['stars']]; Pp = {s['id']: (s['x'], s['y']) for s in c['stars']}
    if len(ids) != 12 or len(set(ids)) != 12: bad.append(c['id'] + ' 별 12 개 아님')
    for a, b in itertools.combinations(ids, 2):
        if math.dist(Pp[a], Pp[b]) < 6: bad.append(f"{c['id']} {a}-{b} 거리 {math.dist(Pp[a], Pp[b]):.1f}")
    for i, (x, y) in Pp.items():
        if not (0 <= x <= 100 and 0 <= y <= 60): bad.append(f"{c['id']} {i} 범위 밖")
    if {i for e in c['order'] for i in e} != set(ids): bad.append(c['id'] + ' 선에 안 닿은 별')
    if any(i not in Pp for e in c['order'] for i in e): bad.append(c['id'] + ' 없는 별 이름')
    c['outline_art'] = c['id'] + '_outline.png'; c['buff']['icon'] = 'buff_' + c['id'] + '.png'; c['edges'] = [list(e) for e in c['order']]
    if c['id'] not in D: bad.append(c['id'] + ' 대사 없음')
def chk(t, w):
    if '…' in t or re.search(r'(?<!\.)\.{3}(?!\.)', t): bad.append(w + ' 점 3 개: ' + t)
    for m in re.finditer(r'\.{2,}', t):
        n = len(m.group(0)); end = re.match(r'[」』)\]”’"\']*[?!]*\s*$', t[m.end():])
        if n != (7 if end else 4): bad.append(f'{w} 점 {n} 개: {t}')
    if '?!' in t or '!!' in t: bad.append(w + ' ?! / !!: ' + t)
for k, v in D.items():
    for f, L in v.items():
        for i, t in enumerate(L): chk(t, f'{k}.{f}[{i}]')
for c in C:
    for e in c['buff']['effects']: pass
    if re.search(r'\d[%가-힣]', c['buff']['desc'].replace('2차', '')): bad.append(c['id'] + ' 숫자 뒤 띄어쓰기: ' + c['buff']['desc'])
if bad:
    print('문제', len(bad)); [print(' ', b) for b in bad]; raise SystemExit(1)
